  await visitor.goto(`${publicPath}?utm_source=Declared%20fictional%20visitor`);await expect(visitor.getByRole('heading',{name:'Fictional workplace equipment inquiry',exact:true})).toBeVisible();await expect(visitor.getByRole('region',{name:'Approved form content'})).toContainText('A fictional equipment team can submit an inquiry for human review.');const image=visitor.getByRole('img',{name:'Declared ERPX icon for the fictional equipment inquiry',exact:true});await expect(image).toBeVisible();await expect.poll(()=>image.evaluate(node=>(node as HTMLImageElement).naturalWidth)).toBeGreaterThan(0);await visitor.screenshot({path:testInfo.outputPath('reviewed-public-marketing-form.png'),fullPage:true});
